    fun getGovernorateByName(name: String): EgyptGovernorateInfo? {
        val clean = name.trim()
            .replace("محافظة ", "")
            .replace(" (المنصورة)", "")
            .replace(" (طنطا)", "")
            .replace(" (الزقازيق)", "")
            .replace(" (بنها)", "")
            .replace(" (شبين الكوم)", "")
            .replace(" (دمنهور)", "")
            .replace(" (الغردقة)", "")
            .replace(" (طور سيناء)", "")
            .replace(" (العريش)", "")
            .replace(" (الخارجة)", "")
            .trim()

        return GOVERNORATES.find {
            it.nameAr.equals(clean, ignoreCase = true) ||
                    it.nameAr.contains(clean) ||
                    clean.contains(it.nameAr)
        }
    }
